/// <summary>
/// Test seam for TEST_MD12RegressionTest. Exposes SJPMDInventCountingService.assignProcessingGroups,
/// which orchestrate only runs inside a batch job, so a test can check the split without one.
/// The method under test runs unchanged.
/// </summary>
public final class TEST_MD12GroupAssigningService extends SJPMDInventCountingService
{
    boolean countFails;
}

Method.Source:
public static TEST_MD12GroupAssigningService construct()
{
    return new TEST_MD12GroupAssigningService();
}

/// <summary>
/// Runs assignProcessingGroups in its own transaction, as orchestrate does.
/// </summary>
public void assign(int _numOfThreads, SJPMDInventCountingFileName _fileName)
{
    ttsbegin;
    this.assignProcessingGroups(_numOfThreads, _fileName);
    ttscommit;
}

/// <summary>
/// countNewRows, the first query orchestrate runs after taking the run lock, throws an
/// error, as a failing SQL statement would.
/// </summary>
public void failCountNewRows()
{
    countFails = true;
}

protected int64 countNewRows(str _fileName)
{
    if (countFails)
    {
        throw error('TEST: countNewRows fault');
    }

    return super(_fileName);
}
